@Override
public void executeOnServer(SkillContainer container, FriendlyByteBuf args) {
    this.setStackSynchronize(container, container.getStack() - 1);
    float yRot = container.getExecutor().getYRot();
    if (args != null && args.isReadable(8)) {
        args.readInt();
        yRot = args.readFloat();
    }
    container.getExecutor().playSound((SoundEvent)EpicFightSounds.EMERGENCY_ESCAPE.get(), 1.0f, 1.0f);
    SPEntityPairingPacket pairingPacket = new SPEntityPairingPacket(((Player)container.getExecutor().getOriginal()).m_19879_(), EntityPairingPacketTypes.EMERGENCY_ESCAPE_ACTIVATED);
    pairingPacket.getBuffer().writeFloat(yRot);
    EpicFightNetworkManager.sendToAllPlayerTrackingThisEntityWithSelf(pairingPacket, (ServerPlayer)container.getServerExecutor().getOriginal(), new Object[0]);
}

